/** A JSON-RPC error with the v1 reason table (README: Errors). */
export class ProtocolError extends Schema.TaggedError<ProtocolError>()("ProtocolError", {
  reason: Schema.String,
  message: Schema.String,
  capability: Schema.optional(Schema.String),
  retryAfterMs: Schema.optional(Schema.Number),
  /** Caveman Cloud's own error code for a refusal the runtime passes on (cloudCallError): RpcError data.cloud_code. */
  cloudCode: Schema.optional(Schema.String),
  /**
   * In-process only, never on the wire: T3 holds a refusal for this message's command (or one sent before it under
   * the same request id), so the request id can never go through, and nothing of the message was delivered. A sender
   * that must get it through (the Chief's notes) sends it again under a new request id.
   */
  refused: Schema.optional(Schema.Boolean),
  /** git.pr in several repositories, when one did not open: the ones that did, and the one that did not (RpcError data.pull_requests). */
  pullRequests: Schema.optional(
    Schema.Struct({
      opened: Schema.Array(Schema.Struct({ source: Schema.String, number: Schema.Number, url: Schema.String })),
      failed: Schema.Struct({ source: Schema.String, reason: Schema.String }),
    }),
  ),
}) {}

/** A Cloud URL as the origin it names, or as typed when it names none (then it matches no pin). */
const originOrRaw = (raw: string) => {
  try {
    return cloudOrigin(raw);
  } catch {
    return raw.trim();
  }
};

const fail = (reason: string, message: string, extra: { capability?: string } = {}) =>
  Effect.fail(new ProtocolError({ reason, message, ...extra }));

/** An image's bytes as base64: a data URL of an image, or base64 that decodes to an image's header. */
const isImageData = (v: string) =>
  /^data:image\/[\w.+-]+;base64,/i.test(v) || (/^[A-Za-z0-9+/]{16}/.test(v) && imageMime("", Buffer.from(v.slice(0, 16), "base64")) !== null);

/**
 * `value` with every string longer than `max` cut to it: an event too large for a transcript page on its own. An image's
 * bytes stay whole: cut, they are no image, and their reader decodes them (chat_read's images view) rather than reads them.
 */
const clipStrings = <T>(value: T, max: number): T => {
  const cut = (v: unknown, depth: number): unknown =>
    typeof v === "string"
      ? v.length > max && !isImageData(v) ? `${v.slice(0, max)}… (${v.length - max} more characters)` : v
      : depth > 12 || v === null || typeof v !== "object"
        ? v
        : Array.isArray(v)
          ? v.map((item) => cut(item, depth + 1))
          : Object.fromEntries(Object.entries(v).map(([k, item]) => [k, cut(item, depth + 1)]));
  return cut(value, 0) as T;
};

/**
 * A Caveman Cloud refusal as a protocol error: Cloud's own sentence, its status as the reason. A 401 here is Cloud
 * refusing the runtime's token even after a new one (computers.ts withRuntimeToken): on This Mac its person signs in
 * again; a Cloud computer's token is its own, which no person can sign in for (kind K14).
 */
const cloudCallError = (error: unknown, onCloudComputer = false) =>
  error instanceof CloudError
    ? new ProtocolError({
        reason: error.status === 409 ? "invalid_state" : enrollReason(error.status),
        message:
          error.status !== 401
            ? error.message
            : onCloudComputer
              ? `Caveman did not accept this Cloud computer's own sign-in (${error.message})`
              : `Sign in to Caveman again: Caveman did not accept your sign-in (${error.message})`,
        // Cloud's code goes on to the client, which offers the way past a limit (m-21: Settings > Computers).
        ...(error.code ? { cloudCode: error.code } : {}),
      })
    : new ProtocolError({ reason: "internal", message: `Could not reach Caveman: ${(error as Error).message}` });

/** The store key holding the image a Cloud computer's setup was last decided on (startSetup). */
const SETUP_IMAGE_KEY = "computer_setup_image";

/** Cloud's update-head refusals that mean the pull request's fork is not Caveman's to write: a follow-up pull request instead. */
const FORK_REFUSALS = new Set(["cave_code_pull_request_fork"]);
/** Cloud's update-head refusal when the pull request's branch is not where the chat last left it. */
const HEAD_MOVED = "cave_code_pull_request_head_moved";

