/** `length` bytes of `file` from `offset` (fewer at its end), and the file's size. */
function readWindow(file: string, offset: number, length: number): { bytes: Buffer; size: number } {
  const fd = fs.openSync(file, "r");
  try {
    const size = fs.fstatSync(fd).size;
    const bytes = Buffer.alloc(Math.max(0, Math.min(length, size - offset)));
    let read = 0;
    while (read < bytes.length) {
      const n = fs.readSync(fd, bytes, read, bytes.length - read, offset + read);
      if (n === 0) break;
      read += n;
    }
    return { bytes: bytes.subarray(0, read), size };
  } finally {
    fs.closeSync(fd);
  }
}

/** `bytes` without a UTF-8 character cut off at its end (at most 3 bytes go); bytes that are no UTF-8 stay as they are. */
export function wholeUtf8(bytes: Buffer): Buffer {
  let start = bytes.length - 1;
  while (start >= 0 && start > bytes.length - 4 && (bytes[start]! & 0xc0) === 0x80) start--;
  if (start < 0) return bytes;
  const lead = bytes[start]!;
  const need = lead >= 0xf8 ? 1 : lead >= 0xf0 ? 4 : lead >= 0xe0 ? 3 : lead >= 0xc0 ? 2 : 1;
  return start + need > bytes.length ? bytes.subarray(0, start) : bytes;
}

/**
 * The first `max` bytes of a blob (`<ref>:<path>`), as bytes: git run directly, or in the tools container on a
 * Cloud computer, as the git driver runs it. The driver's output is text, which garbles a binary file.
 */
function blobBytes(worktree: string, spec: string, max: number): Promise<Buffer> {
  return new Promise((resolve, reject) => {
    const args = ["cat-file", "blob", "--end-of-options", spec];
    const socket = toolsSocket();
    const routed = socket === undefined ? { command: "git", args, env: {} } : toolsCommand(socket, "git", args, worktree, {});
    const child = spawn(routed.command, routed.args, { ...(socket === undefined ? { cwd: worktree } : {}), env: { ...process.env, ...routed.env }, stdio: ["ignore", "pipe", "ignore"], windowsHide: true });
    const chunks: Array<Buffer> = [];
    let length = 0;
    let enough = false;
    child.stdout.on("data", (chunk: Buffer) => {
      if (enough) return;
      chunks.push(chunk);
      length += chunk.length;
      if (length >= max) {
        enough = true;
        child.kill();
      }
    });
    child.on("error", reject);
    child.on("close", (code) => (enough || code === 0 ? resolve(Buffer.concat(chunks).subarray(0, max)) : reject(new Error(`git cat-file exited ${code}`))));
  });
}
