  if (grillModeRefusal(pin.engine, p.options?.mode) !== null) return undefined;
  const { model: _m, effort: _e, speed: _s, account_id: _a, engine: _n, ...kept } = p.options ?? {};
  return { ...p, engine: pin.engine, options: { ...kept, model: pin.model, account_id: pin.instance_id, ...(pin.effort ? { effort: pin.effort } : {}) } };
