      if (goal && !goal.native) p = { ...p, instructions: withGoal(goal.objective, p.instructions ?? p.input.text) };
      if (p.instructions !== undefined && p.instructions !== p.input.text) {
        yield* store.sql`INSERT OR REPLACE INTO caveman_sp_display_text (message_id, text) VALUES (${messageId}, ${p.input.text})`.pipe(Effect.orDie);
      }
