      // A linked thread's digest carries its latest answer here, and what that thread read outside with it.
      if (Option.isSome(memory)) for (const linked of records) yield* memory.value.carryTaint(linked.threadId, record.internal.threadId);
      const result = yield* dispatchBefore({
        type: "message.dispatch",
 // Notifications are server-created and queued (upstream rule).
        ...(p.notification !== undefined
          ? { createdBy: "agent" as const, creationSource: "server" as const, notification: p.notification }
          : { createdBy: "user" as const, creationSource: "web" as const }),
        commandId: commandId(record.session.id, p.request_id),
        threadId,
        messageId,
        text,
        ...(records.length > 0 ? { context: { version: 1 as const, records } } : {}),
        attachments: stored.attachments,
        ...(p.titleSeed ? { titleSeed: p.titleSeed, titleSource: replaceComposerContextReferences(p.input.text, (ref) => ref.label) } : {}),
        ...(modelSelection ? { modelSelection } : {}),
        dispatchMode: p.notification !== undefined ? { type: "queue_after_active" } : dispatchMode,
      }).pipe(Effect.tapError(() => Effect.sync(() => removeStoredAttachments(storedPaths))));
