      // ends. A queued input, mail or a goal leaves it open. (Dispatch only records the input, so the
      // turn blocked on the round never holds it up.)
      if (!p.generated && p.kind !== "queue" && !(switchingEngine && disposition === "queued")) yield* grill.cancelOpen(record);
      const created = result.storedEvents.find(
        (stored): stored is typeof stored & { event: Extract<OrchestrationV2DomainEvent, { type: "run.created" }> } =>
          stored.event.type === "run.created",
      );
      const turnId = disposition === "steered" ? active!.id : (created?.event.payload.id ?? runs.find((r) => r.userMessageId === messageId)?.id);
      // T3 has the message from here: what follows only places it, and its answer says it was taken (a resend would
