      const held = yield* heldOf(sessionId);
      if (held !== undefined && held.commit === sent && (held.baseline === EMPTY_TREE || (yield* hasCommit(repoPath, held.baseline)))) return held.baseline;
      if (sent && (yield* hasCommit(repoPath, sent))) return sent;
