        yield* rejectSecretInput(projectSecrets, p.text);
        const record = yield* recordBySession(p.session_id).pipe(Effect.flatMap(live));
        const { turn } = yield* queuedTurn(record, p.turn_id);
        const projection = yield* orchestrator.getThreadProjection(ThreadId.make(record.internal.threadId)).pipe(Effect.orElseSucceed(() => undefined));
        const messageId = projection?.runs.find((r) => r.id === p.turn_id)?.userMessageId;
        // The edit keeps the grill marker the input was sent with (the skill, or the end notice).
        const marked = withGrillMarker(grillMarkerOf(projection?.messages.find((m) => m.id === messageId)?.text ?? ""), p.text);
        const goal = record.internal.goal;
        const sent = goal && !goal.native ? withGoal(goal.objective, marked) : marked;
        if (messageId && sent !== p.text) {
          yield* store.sql`INSERT OR REPLACE INTO caveman_sp_display_text (message_id, text) VALUES (${messageId}, ${p.text})`.pipe(Effect.orDie);
        } else if (messageId) {
          yield* store.sql`DELETE FROM caveman_sp_display_text WHERE message_id = ${messageId}`.pipe(Effect.orDie);
        }
