        const turnId = yield* turnDoneAt(record, p.at);
        const caps = yield* capabilitiesOf(record.workspace.engine);
        if (caps && !(caps.threads.canRollbackThread && caps.threads.canForkFromTurn && caps.checkpointing.appCanCheckpointFilesystem)) {
          return yield* fail("unsupported", `${record.workspace.engine} cannot restore to a turn`, { capability: "restore" });
        }
        const threadId = ThreadId.make(record.internal.threadId);
        const projection = yield* orchestrator.getThreadProjection(threadId).pipe(Effect.orElseSucceed(() => undefined));
        if (!projection) return yield* fail("not_found", `no thread for session ${p.session_id}`);
        if (projection.runs.some((run) => ACTIVE.has(run.status))) return yield* fail("invalid_state", "stop the running turn (and clear the queue) before restoring");
        const target = projection.runs.find((r) => r.id === turnId);
