          // A turn from before this computer took the chat from its copy (a Cloud computer back on its chats, or a
          // move): the engine thread here has no run for it, but its checkpoint may have come with the copy
          // (MoveBundle.checkpoints, R1 of cloud-computers-2026-11-09). The files go back to it, what came after is kept
          // as a branch where a turn that ran here can be forked (else on the restore's own ref), and the engine carries
          // on in a new session handed the conversation up to that turn, as a session that would not resume is
          // (handOverIfResumeFailed).
          const engineId = record.workspace.engine;
          const before = "that turn ran before this chat came to this computer";
          if (!isNativeEngine(engineId)) return yield* fail("unsupported", `${before}; it cannot be restored to here`, { capability: "restore" });
          const worktree = yield* worktreeOf(record);
          const named = yield* store.sql<{ ref: string | null }>`SELECT json_extract(event, '$.payload.ref') AS ref FROM caveman_sp_events
            WHERE session_id = ${record.session.id} AND type = 'checkpoint.created' AND json_extract(event, '$.turn_id') = ${turnId} ORDER BY cursor DESC LIMIT 1`.pipe(Effect.orDie);
          const ref = named[0]?.ref;
