        // starts where it began (its baseline), not at the base, which a chat's first turn may not have started from (the
        // person's own edits, another agent's), nor at the turn before's end, which the person may have edited since.
        // Any other `to` (a ref, a fork's copied turn) keeps the base as its start.
        const turn = p.to?.startsWith("checkpoint:") === true ? Option.getOrUndefined(yield* Effect.option(finishedTurn(record, p.to))) : undefined;
        const baseline = turn?.baseline;
        const own = baseline !== undefined && (p.from === undefined || p.from === baseline.id);
        // A ref named outright (a checkpoint, a commit): the same in every source of the chat, read once.
        const named = own || p.from === undefined || p.from === record.workspace.base_ref ? undefined : yield* checkpointRef(record, p.from);
        const until = p.to === undefined ? undefined : yield* checkpointRef(record, p.to);
