            const internal = makeServerInternalPathCheck(config);
            const newFiles = (untracked?.stdout.split("\0").filter(Boolean) ?? []).filter((file) => !internal(path.join(worktree, file)));
            const added = (yield* gitOrFail(untrackedPatches(driver, worktree, newFiles))).map(
              ({ path: file, patch }) => ({
                path: file,
                status: "added" as const,
                additions: patch.split("\n").filter((l) => l.startsWith("+") && !l.startsWith("+++")).length,
                deletions: 0,
                patch,
              }),
            );
            return [...files, ...added];
