        const found = yield* launcher.value.resolveAvailableEditors();
        const reveal = found.includes("file-manager") && (yield* launcher.value.resolveFileManagerRevealKind()) !== undefined;
        const editors = EDITORS.filter((e) => e.id !== "file-manager" && found.includes(e.id)).map((e) => ({ id: e.id, label: e.label }));
