        if (!fs.existsSync(file)) return yield* fail("not_found", `no file ${p.path}`);
        if (Option.isNone(launcher)) return yield* fail("unsupported", "this computer opens no editors");
        const found = yield* launcher.value.resolveAvailableEditors();
